/**
 * Passage 1: grind the ink, then the far grove in the palest washes.
 *
 * Sumi-e works in five inks from one stick: jiao (burnt, the blackest), nong (thick),
 * zhong (middle), dan (light), and qing (clear, a breath of grey). They are mixed here
 * from two soots and water and kept for every later passage. The far grove goes down
 * first, in qing and dan: thin culms that rise out of the mist and leave the top edge,
 * with small sprays of leaves. Their feet thin out into nothing, and that empty paper
 * is the mist the nearer bamboo stands in front of.
 */

// The ink stick and the water dish. Pine soot is cool and blue-black, oil soot warm.
palette('pineSoot', '#14181f');
palette('oilSoot', '#1f1915');
palette('water', '#f1efe9');

// The five inks, ground from the same black and let down with water.
palette('jiao', mix(['pineSoot', 1.4], ['oilSoot', 1]));
palette('nong', mix(['jiao', 1], ['water', 0.35]));
palette('zhong', mix(['jiao', 1], ['water', 1.6]));
palette('dan', mix(['jiao', 1], ['water', 5]));
palette('qing', mix(['jiao', 1], ['water', 16]));

const W = canvas.width;
const H = canvas.height;
const clamp = (v) => Math.max(0, Math.min(1, v));

/** A point on a cubic Bézier through four [x, y] control points. */
function bez(p, t) {
  const u = 1 - t;
  return [
    u * u * u * p[0][0] + 3 * u * u * t * p[1][0] + 3 * u * t * t * p[2][0] + t * t * t * p[3][0],
    u * u * u * p[0][1] + 3 * u * u * t * p[1][1] + 3 * u * t * t * p[2][1] + t * t * t * p[3][1],
  ];
}

/**
 * One distant culm: segments between nodes, each a single flat stroke, the brush lifted
 * at every node. Below `fadeY` the ink thins with each segment until it gives out.
 * Returns the nodes, for the branches.
 */
function farCulm(ctrl, width, pile, fadeY) {
  const pts = [];
  for (let i = 0; i <= 240; i++) pts.push(bez(ctrl, i / 240));
  const arc = [0];
  for (let i = 1; i < pts.length; i++) {
    arc.push(arc[i - 1] + Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]));
  }
  const L = arc[arc.length - 1];
  const at = (s) => {
    const i = arc.findIndex((a) => a >= s);
    return pts[i < 0 ? pts.length - 1 : i];
  };
  const nodes = [0];
  while (nodes[nodes.length - 1] < L) {
    const t = nodes[nodes.length - 1] / L;
    nodes.push(
      nodes[nodes.length - 1] +
        (110 + 120 * Math.sin(Math.PI * Math.min(1, t * 1.3))) * rand(0.9, 1.1),
    );
  }
  const gap = width * 0.45;
  const out = [];
  for (let i = 0; i < nodes.length - 1; i++) {
    const a = nodes[i] + gap / 2;
    const b = Math.min(L, nodes[i + 1] - gap / 2);
    if (b - a < 20) continue;
    const path = [];
    for (let s = a; s <= b; s += 18) path.push(at(s));
    path.push(at(b));
    const y = at((a + b) / 2)[1];
    const fade = clamp((y - fadeY) / 260);
    if (fade >= 1) continue;
    // toward the mist each segment goes down a step: the pile let down with more water
    const step = fade <= 0 ? 0 : fade < 0.5 ? 1 : 2;
    stroke({
      path,
      brush: { type: 'flat', width: width * (1 - 0.25 * (a / L)), streak: 0.5, toneVar: 0.3 },
      color: [pile, mix([pile, 2], ['water', 1]), mix([pile, 1], ['water', 2])][step],
      paint: 'transparent',
      thinner: [0.2, 0.4, 0.65][step],
      load: [0.75, 0.7, 0.6][step],
      end: 'stop',
    });
    if (i > 0 && fade < 0.5) out.push({ s: nodes[i], p: at(nodes[i]), q: at(nodes[i] + 6) });
  }
  return out;
}

/** A leaf: the tip of the brush touches, presses down, and lifts away to a point. */
function leaf(x, y, ang, len, wid, pile, bend) {
  const pts = [];
  let h = ang;
  let px = x;
  let py = y;
  for (let k = 0; k <= 12; k++) {
    const t = k / 12;
    const p =
      t < 0.06 ? 0.05 : t < 0.28 ? ((t - 0.06) / 0.22) ** 0.7 : 1 - ((t - 0.28) / 0.72) ** 1.5;
    pts.push([px, py, clamp(p)]);
    h += (bend * 2 * (1 - t)) / 12;
    px += (Math.cos(h) * len) / 12;
    py += (Math.sin(h) * len) / 12;
  }
  stroke({
    path: pts,
    brush: { type: 'round', width: wid, streak: 0.12, toneVar: 0.12 },
    color: pile,
    paint: 'transparent',
    thinner: 0.15,
    load: 0.9,
    end: rand() < 0.3 ? 'flick' : 'taper',
  });
}

/** A twig off a node, and a spray of leaves hanging from its end, heavy with rain. */
function spray(node, side, pile, scale, count) {
  const [nx, ny] = node.p;
  const up = Math.atan2(node.q[1] - ny, node.q[0] - nx);
  const out = up + side * rand(0.7, 1.0);
  const len = rand(70, 130) * scale;
  const tip = [nx + Math.cos(out) * len, ny + Math.sin(out) * len + len * 0.15];
  stroke({
    path: [
      [nx, ny, 0.8],
      [(nx + tip[0]) / 2, (ny + tip[1]) / 2 - 6, 0.5],
      [tip[0], tip[1], 0.25],
    ],
    brush: { type: 'round', width: 4 * scale + 1, streak: 0.2 },
    color: pile,
    paint: 'transparent',
    load: 0.8,
    end: 'flick',
  });
  const hang = Math.PI / 2 - side * 0.35;
  for (let i = 0; i < count; i++) {
    const f = count === 1 ? 0 : i / (count - 1) - 0.5;
    leaf(
      tip[0] + rand(-3, 3),
      tip[1] + rand(-3, 3),
      hang + f * 1.3 + rand(-0.12, 0.12),
      rand(80, 125) * scale * (1 - Math.abs(f) * 0.35),
      rand(17, 22) * scale,
      pile,
      -f * 0.35 + rand(-0.1, 0.1),
    );
  }
}

// The farthest culms, in qing: one at the left, two at the right edge.
const FARTHEST = [
  {
    ctrl: [
      [175, 1500],
      [168, 1000],
      [150, 500],
      [128, -30],
    ],
    w: 13,
    fade: 1080,
  },
  {
    ctrl: [
      [985, 1500],
      [990, 1050],
      [1010, 500],
      [1040, -30],
    ],
    w: 14,
    fade: 1120,
  },
  {
    ctrl: [
      [1080, 1500],
      [1075, 1100],
      [1068, 500],
      [1078, -30],
    ],
    w: 11,
    fade: 980,
  },
];
// Nearer, in dan: two culms that will stand between the middle grove's.
const NEARER = [
  {
    ctrl: [
      [640, 1600],
      [650, 1100],
      [680, 500],
      [735, -30],
    ],
    w: 17,
    fade: 1230,
  },
  {
    ctrl: [
      [880, 1600],
      [872, 1150],
      [850, 600],
      [868, -30],
    ],
    w: 16,
    fade: 1300,
  },
];

for (const c of FARTHEST) {
  const nodes = farCulm(c.ctrl, c.w, 'qing', c.fade);
  for (const n of nodes) {
    if (rand() < 0.45 || n.p[1] > c.fade - 80) continue;
    spray(n, n.p[0] < W / 2 ? 1 : -1, 'qing', 0.75, 3 + Math.floor(rand(3)));
  }
}
for (const c of NEARER) {
  const nodes = farCulm(c.ctrl, c.w, 'dan', c.fade);
  nodes.forEach((n, i) => {
    if (n.p[1] > c.fade - 60 || n.p[1] < 80) return;
    if (i % 2 === 1 && rand() < 0.8)
      spray(n, i % 4 === 1 ? 1 : -1, 'dan', 0.9, 3 + Math.floor(rand(3)));
  });
}

// The grove's farthest leaves, seen through the mist: sprays in qing with no twig in
// sight, hanging off the top edge.
for (let i = 0; i < 6; i++) {
  const x = [70, 260, 560, 790, 960, 1060][i] + rand(-20, 20);
  const y = rand(-10, 60);
  const n = 3 + Math.floor(rand(3));
  for (let k = 0; k < n; k++) {
    const f = k / (n - 1) - 0.5;
    leaf(
      x,
      y,
      Math.PI / 2 + f * 1.2 + rand(-0.15, 0.15),
      rand(70, 110),
      rand(15, 19),
      'qing',
      -f * 0.3,
    );
  }
}

show({ x: 0, y: 0, w: W, h: H }, { mode: 'color', maxSide: 900 });
dry();

/**
 * Passage 2: the middle grove, in zhong.
 *
 * Two culms a step nearer: one rises straight past the right of center; the other
 * starts at the bottom edge and arches over to the right, its top bowed by wet leaves.
 * Each segment is one flat stroke, lifted at the node; the nodes go on afterward in
 * nong, a shade darker, as two short strokes across the gap. Leaves hang in sprays of
 * three to six from twigs, and the arch's tip ends in a cascade of them.
 */

const W = canvas.width;
const clamp = (v) => Math.max(0, Math.min(1, v));

function bez(p, t) {
  const u = 1 - t;
  return [
    u * u * u * p[0][0] + 3 * u * u * t * p[1][0] + 3 * u * t * t * p[2][0] + t * t * t * p[3][0],
    u * u * u * p[0][1] + 3 * u * u * t * p[1][1] + 3 * u * t * t * p[2][1] + t * t * t * p[3][1],
  ];
}

/** A culm's spine sampled by arc length: `at(s)` is the point s px up from the base. */
function spine(ctrl) {
  const pts = [];
  for (let i = 0; i <= 300; i++) pts.push(bez(ctrl, i / 300));
  const arc = [0];
  for (let i = 1; i < pts.length; i++) {
    arc.push(arc[i - 1] + Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]));
  }
  const at = (s) => {
    const i = arc.findIndex((a) => a >= s);
    return pts[i < 0 ? pts.length - 1 : i];
  };
  return { at, length: arc[arc.length - 1] };
}

/**
 * Lay a culm: one flat stroke per segment, then a node across each gap in `nodeInk`.
 * Width runs from `w0` at the base to `w1` at the top. Returns the nodes.
 */
function culm(ctrl, w0, w1, ink, nodeInk, internodes) {
  const sp = spine(ctrl);
  const L = sp.length;
  const nodes = [0];
  for (const len of internodes) nodes.push(Math.min(L, nodes[nodes.length - 1] + len));
  const width = (s) => w0 + (w1 - w0) * (s / L);
  for (let i = 0; i < nodes.length - 1; i++) {
    const gap = width(nodes[i]) * 0.4;
    const a = nodes[i] + gap / 2;
    const b = nodes[i + 1] - (i === nodes.length - 2 ? 0 : gap / 2);
    if (b - a < 12) continue;
    const path = [];
    for (let s = a; s < b; s += 16) path.push([...sp.at(s), 0.95]);
    path.push([...sp.at(b), 1]);
    stroke({
      path,
      brush: {
        type: 'flat',
        width: width((a + b) / 2),
        streak: 0.55,
        toneVar: 0.35,
        stiffness: 0.5,
      },
      color: ink,
      paint: 'transparent',
      thinner: rand(0.05, 0.2),
      load: rand(0.75, 0.9),
      contact: rand(0.82, 0.95),
      end: i === nodes.length - 2 ? 'taper' : 'stop',
    });
  }
  const out = [];
  for (let i = 1; i < nodes.length - 1; i++) {
    const p = sp.at(nodes[i]);
    const q = sp.at(nodes[i] + 8);
    const d = [(q[0] - p[0]) / 8, (q[1] - p[1]) / 8];
    const n = [-d[1], d[0]];
    const hw = width(nodes[i]) / 2;
    const pt = (u, v, pr) => [p[0] + n[0] * u + d[0] * v, p[1] + n[1] * u + d[1] * v, pr];
    const nw = Math.max(3, hw * 0.32);
    stroke({
      path: [pt(-hw - 3, 2, 0.7), pt(-hw * 0.45, -1.5, 0.9), pt(-1, 0, 0.35)],
      brush: { type: 'round', width: nw, streak: 0 },
      color: nodeInk,
      paint: 'transparent',
      load: 0.9,
      end: 'taper',
    });
    stroke({
      path: [pt(1, 0, 0.35), pt(hw * 0.45, -1.5, 0.9), pt(hw + 3, 2, 0.6)],
      brush: { type: 'round', width: nw, streak: 0 },
      color: nodeInk,
      paint: 'transparent',
      load: 0.9,
      end: 'flick',
    });
    out.push({ p, d, hw });
  }
  return out;
}

/** A leaf: the tip touches, the brush presses down, and lifts away to a point. */
function leaf(x, y, ang, len, wid, ink, bend) {
  const pts = [];
  let h = ang;
  let px = x;
  let py = y;
  for (let k = 0; k <= 12; k++) {
    const t = k / 12;
    const p =
      t < 0.06 ? 0.05 : t < 0.28 ? ((t - 0.06) / 0.22) ** 0.7 : 1 - ((t - 0.28) / 0.72) ** 1.5;
    pts.push([px, py, clamp(p)]);
    h += (bend * 2 * (1 - t)) / 12;
    px += (Math.cos(h) * len) / 12;
    py += (Math.sin(h) * len) / 12;
  }
  stroke({
    path: pts,
    brush: { type: 'round', width: wid, streak: 0.12, toneVar: 0.15 },
    color: ink,
    paint: 'transparent',
    thinner: rand(0, 0.15),
    load: 0.9,
    end: rand() < 0.3 ? 'flick' : 'taper',
  });
}

/**
 * Leaves hanging from one twig end around `hang`: long and narrow, unevenly fanned,
 * the middle ones longest, each curving away from the others.
 */
function hangLeaves(tip, hang, count, scale, ink) {
  for (let i = 0; i < count; i++) {
    const f = count === 1 ? 0 : i / (count - 1) - 0.5;
    leaf(
      tip[0] + rand(-5, 5),
      tip[1] + rand(-5, 5),
      hang + f * rand(1.2, 1.55) + rand(-0.18, 0.18),
      rand(145, 200) * scale * (1 - Math.abs(f) * 0.4),
      rand(20, 25) * scale,
      ink,
      -f * 0.45 + rand(-0.12, 0.12),
    );
  }
}

/** A twig from a node out to one side, bending down at its end; returns its tip. */
function twig(node, side, len, ink) {
  const up = Math.atan2(node.d[1], node.d[0]);
  const out = up + side * rand(0.75, 1.05);
  const [x, y] = [
    node.p[0] + Math.cos(up + side * 1.57) * node.hw,
    node.p[1] + Math.sin(up + side * 1.57) * node.hw,
  ];
  const tip = [x + Math.cos(out) * len, y + Math.sin(out) * len + len * 0.22];
  stroke({
    path: [
      [x, y, 0.85],
      [x + Math.cos(out) * len * 0.5, y + Math.sin(out) * len * 0.5 - 4, 0.6],
      [tip[0], tip[1], 0.3],
    ],
    brush: { type: 'round', width: 6, streak: 0.25 },
    color: ink,
    paint: 'transparent',
    load: 0.85,
    end: 'flick',
  });
  return tip;
}

// The straight culm, right of center.
const straight = culm(
  [
    [790, 1890],
    [805, 1300],
    [758, 620],
    [812, -30],
  ],
  27,
  21,
  'zhong',
  'nong',
  [140, 170, 205, 225, 230, 230, 220, 210, 200, 190],
);
straight.forEach((n, i) => {
  if (n.p[1] < 60 || n.p[1] > 1350) return;
  if (i % 2 === 0)
    hangLeaves(
      twig(n, i % 4 === 0 ? 1 : -1, rand(90, 140), 'zhong'),
      Math.PI / 2 + (i % 4 === 0 ? -0.35 : 0.35),
      4 + Math.floor(rand(3)),
      1,
      'zhong',
    );
});

// The arching culm: up from the bottom edge, bowed over to the right by its wet crown.
const archCtrl = [
  [545, 1890],
  [560, 1050],
  [690, 400],
  [985, 300],
];
const arch = culm(
  archCtrl,
  26,
  9,
  'zhong',
  'nong',
  [130, 165, 200, 220, 225, 220, 205, 185, 160, 130, 105, 90, 80],
);
arch.forEach((n, i) => {
  if (n.p[1] > 1300) return;
  if (i % 2 === 1)
    hangLeaves(
      twig(n, -1, rand(70, 120), 'zhong'),
      Math.PI / 2 + rand(-0.2, 0.2),
      3 + Math.floor(rand(3)),
      0.95,
      'zhong',
    );
  else if (n.p[1] < 700)
    hangLeaves(
      twig(n, 1, rand(60, 100), 'zhong'),
      Math.PI / 2 + rand(-0.3, 0.1),
      3 + Math.floor(rand(2)),
      0.9,
      'zhong',
    );
});
// The cascade off the arch's tip: leaves stacked down from the bowed end.
const archTip = bez(archCtrl, 1);
for (let k = 0; k < 4; k++) {
  hangLeaves(
    [archTip[0] - 30 * k + rand(-8, 8), archTip[1] + 18 * k],
    Math.PI / 2 - 0.1 + k * 0.12,
    4 + (k % 2),
    1.05 - k * 0.06,
    k === 0 ? 'nong' : 'zhong',
  );
}

show({ x: 0, y: 0, w: W, h: canvas.height }, { mode: 'color', maxSide: 900 });
dry();

/**
 * Passage 3: the front culm, in nong, its nodes in jiao.
 *
 * The one culm in front of everything: it comes in at the bottom edge left of center
 * and bends right as it climbs, leaving at the top. Each segment is a single flat
 * stroke with the brush pressed at the start and squared off at the node; the paper
 * catches only some of the bristles, so the stroke breaks into the streaks of flying
 * white. The brush is reloaded every segment or two, so the ink drifts between nong
 * and a nong deepened with jiao. The nodes go on last, in jiao, while the segments
 * are still wet, so their ends soften a little into the culm.
 */

palette('nongDeep', mix(['nong', 2], ['jiao', 1]));
palette('nongDark', mix(['nong', 1], ['jiao', 1.3]));

function bez(p, t) {
  const u = 1 - t;
  return [
    u * u * u * p[0][0] + 3 * u * u * t * p[1][0] + 3 * u * t * t * p[2][0] + t * t * t * p[3][0],
    u * u * u * p[0][1] + 3 * u * u * t * p[1][1] + 3 * u * t * t * p[2][1] + t * t * t * p[3][1],
  ];
}

function spine(ctrl) {
  const pts = [];
  for (let i = 0; i <= 400; i++) pts.push(bez(ctrl, i / 400));
  const arc = [0];
  for (let i = 1; i < pts.length; i++) {
    arc.push(arc[i - 1] + Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]));
  }
  const at = (s) => {
    const i = arc.findIndex((a) => a >= s);
    return pts[i < 0 ? pts.length - 1 : i];
  };
  return { at, length: arc[arc.length - 1] };
}

// The front culm's line and its internodes, base to top (passage 4 uses the same).
const FRONT = [
  [290, 1900],
  [292, 1250],
  [355, 640],
  [530, -45],
];
const INTERNODES = [150, 175, 205, 222, 232, 236, 230, 220, 210, 200];
const W0 = 44;
const W1 = 31;

const sp = spine(FRONT);
const L = sp.length;
const nodes = [0];
for (const len of INTERNODES) nodes.push(Math.min(L, nodes[nodes.length - 1] + len));
if (nodes[nodes.length - 1] < L) nodes.push(L);
const width = (s) => W0 + (W1 - W0) * (s / L);

let ink = 'nongDeep';
for (let i = 0; i < nodes.length - 1; i++) {
  if (i % 2 === 0) ink = rand() < 0.5 ? 'nongDeep' : 'nongDark';
  const gap = width(nodes[i]) * 0.36;
  const a = nodes[i] + gap / 2;
  const last = i === nodes.length - 2;
  const b = nodes[i + 1] - (last ? 0 : gap / 2);
  const path = [];
  for (let s = a; s < b; s += 14) {
    const t = (s - a) / (b - a);
    // pressed at the start, eased through the middle, pressed again into the node
    path.push([...sp.at(s), t < 0.12 ? 1 : t > 0.9 ? 1 : 0.88]);
  }
  path.push([...sp.at(b), 1]);
  stroke({
    path,
    brush: {
      type: 'flat',
      width: width((a + b) / 2),
      streak: 0.7,
      toneVar: 0.4,
      stiffness: 0.45,
      splay: 0.15,
    },
    color: ink,
    paint: 'transparent',
    thinner: rand(0, 0.1),
    load: rand(0.8, 0.95),
    contact: rand(0.72, 0.86),
    end: last ? 'lift' : 'stop',
  });
}

// The nodes: one stroke across each gap, pressed at the culm's edges where the ring
// bulges, lighter through the middle, its ends curling up toward the segment above.
for (let i = 1; i < nodes.length - 1; i++) {
  const p = sp.at(nodes[i]);
  const q = sp.at(nodes[i] + 8);
  const d = [(q[0] - p[0]) / 8, (q[1] - p[1]) / 8];
  const n = [-d[1], d[0]];
  const hw = width(nodes[i]) / 2;
  const pt = (u, v, pr) => [p[0] + n[0] * u + d[0] * v, p[1] + n[1] * u + d[1] * v, pr];
  stroke({
    path: [
      pt(-hw - 5, 4, 0.75),
      pt(-hw * 0.6, -1, 1),
      pt(0, -2.5, 0.45),
      pt(hw * 0.6, -1, 1),
      pt(hw + 5, 4, 0.7),
    ],
    brush: { type: 'round', width: hw * 0.3, streak: 0.15 },
    color: 'jiao',
    paint: 'transparent',
    load: 0.95,
    end: rand() < 0.5 ? 'flick' : 'taper',
  });
}

show({ x: 160, y: 900, w: 360, h: 500 }, { mode: 'color', maxSide: 720 });
dry();

/**
 * Passage 4: the front branches and leaves, in jiao and nong.
 *
 * The darkest strokes in the painting. Branches leave the front culm's nodes, alternating
 * sides as they climb, each a single stroke that thins as the brush lifts, with a
 * twig or two off it. The leaves hang from the twig ends in groups, wet with rain: each
 * one a single stroke, the tip of the brush touching down, the body pressed out, the
 * brush lifting away to a point. The brush is dipped in jiao for the leaves in front of
 * a group and in nong for those behind; where two overlap the ink deepens. A last few
 * young leaves at the top are left paler.
 */

const clamp = (v) => Math.max(0, Math.min(1, v));

function bez(p, t) {
  const u = 1 - t;
  return [
    u * u * u * p[0][0] + 3 * u * u * t * p[1][0] + 3 * u * t * t * p[2][0] + t * t * t * p[3][0],
    u * u * u * p[0][1] + 3 * u * u * t * p[1][1] + 3 * u * t * t * p[2][1] + t * t * t * p[3][1],
  ];
}

function spine(ctrl) {
  const pts = [];
  for (let i = 0; i <= 400; i++) pts.push(bez(ctrl, i / 400));
  const arc = [0];
  for (let i = 1; i < pts.length; i++) {
    arc.push(arc[i - 1] + Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]));
  }
  const at = (s) => {
    const i = arc.findIndex((a) => a >= s);
    return pts[i < 0 ? pts.length - 1 : i];
  };
  return { at, length: arc[arc.length - 1] };
}

// The front culm, as passage 3 laid it.
const FRONT = [
  [290, 1900],
  [292, 1250],
  [355, 640],
  [530, -45],
];
const INTERNODES = [150, 175, 205, 222, 232, 236, 230, 220, 210, 200];
const W0 = 44;
const W1 = 31;
const sp = spine(FRONT);
const L = sp.length;
const nodes = [0];
for (const len of INTERNODES) nodes.push(nodes[nodes.length - 1] + len);

/** The node `i` as a point, its up-the-culm direction, and the culm's half width there. */
function node(i) {
  const p = sp.at(nodes[i]);
  const q = sp.at(nodes[i] + 8);
  return {
    p,
    d: [(q[0] - p[0]) / 8, (q[1] - p[1]) / 8],
    hw: (W0 + (W1 - W0) * (nodes[i] / L)) / 2,
  };
}

/** A leaf: the tip touches, the brush presses down, and lifts away to a point. */
function leaf(x, y, ang, len, wid, ink, bend) {
  const pts = [];
  let h = ang;
  let px = x;
  let py = y;
  for (let k = 0; k <= 14; k++) {
    const t = k / 14;
    const p =
      t < 0.05 ? 0.05 : t < 0.27 ? ((t - 0.05) / 0.22) ** 0.7 : 1 - ((t - 0.27) / 0.73) ** 1.5;
    pts.push([px, py, clamp(p)]);
    h += (bend * 2 * (1 - t)) / 14;
    px += (Math.cos(h) * len) / 14;
    py += (Math.sin(h) * len) / 14;
  }
  stroke({
    path: pts,
    brush: { type: 'round', width: wid, streak: 0.12, toneVar: 0.15 },
    color: ink,
    paint: 'transparent',
    thinner: ink === 'jiao' ? 0 : rand(0, 0.1),
    load: 0.95,
    end: rand() < 0.3 ? 'flick' : 'taper',
  });
}

/**
 * A group of leaves hanging from one twig end: fanned unevenly around `hang`, the
 * middle ones longest, the first `front` of them in jiao and the rest in nong.
 */
function group(tip, hang, count, scale, front) {
  // shuffle which leaf of the fan goes on when; the last `front` laid are the jiao ones
  const order = [];
  for (let i = 0; i < count; i++) order.push(i);
  for (let i = count - 1; i > 0; i--) {
    const j = Math.floor(rand(i + 1));
    [order[i], order[j]] = [order[j], order[i]];
  }
  order.forEach((i, k) => {
    const f = count === 1 ? 0 : i / (count - 1) - 0.5;
    leaf(
      tip[0] + rand(-5, 5),
      tip[1] + rand(-5, 5),
      hang + f * rand(1.4, 1.8) + rand(-0.15, 0.15),
      rand(215, 285) * scale * (1 - Math.abs(f) * 0.35),
      rand(28, 34) * scale,
      k >= count - front ? 'jiao' : 'nong',
      -f * 0.55 + rand(-0.12, 0.12),
    );
  });
}

/**
 * A branch from node `i` out to `side` (1 right, -1 left), `len` px long, drooping by
 * `droop` px at its end. Returns points along it, from the culm out, for twigs.
 */
function branch(i, side, len, droop) {
  const nd = node(i);
  const up = Math.atan2(nd.d[1], nd.d[0]);
  const out = up + side * 0.85;
  const start = [
    nd.p[0] + Math.cos(up + side * 1.57) * nd.hw,
    nd.p[1] + Math.sin(up + side * 1.57) * nd.hw,
  ];
  const pts = [];
  for (let k = 0; k <= 4; k++) {
    const t = k / 4;
    pts.push([
      start[0] + Math.cos(out) * len * t,
      start[1] + Math.sin(out) * len * t + droop * t * t,
      0.95 - t * 0.6,
    ]);
  }
  stroke({
    path: pts,
    brush: { type: 'round', width: 9, streak: 0.3 },
    color: 'nongDeep',
    paint: 'transparent',
    load: 0.9,
    end: 'flick',
  });
  // the branch's own node, a dark tick a third of the way out
  const m = pts[1];
  stroke({
    path: [
      [m[0] - 5, m[1] - 3],
      [m[0] + 5, m[1] + 3],
    ],
    brush: { type: 'round', width: 4 },
    color: 'jiao',
    paint: 'semi_opaque',
    load: 0.8,
    end: 'taper',
  });
  return pts;
}

/** A twig off a branch point, ending where a group of leaves hangs. */
function twig(from, ang, len) {
  const tip = [from[0] + Math.cos(ang) * len, from[1] + Math.sin(ang) * len];
  stroke({
    path: [
      [from[0], from[1], 0.7],
      [(from[0] + tip[0]) / 2, (from[1] + tip[1]) / 2 - 3, 0.5],
      [tip[0], tip[1], 0.25],
    ],
    brush: { type: 'round', width: 5, streak: 0.2 },
    color: 'nong',
    paint: 'transparent',
    load: 0.85,
    end: 'flick',
  });
  return tip;
}

// Low on the left: a long branch reaching out over the empty paper, two heavy groups.
const b1 = branch(3, -1, 190, 50);
group(b1[4], Math.PI / 2 + 0.35, 7, 1, 3);
group(twig(b1[2], Math.PI - 0.2, 70), Math.PI / 2 + 0.55, 5, 0.9, 2);

// Above it on the right: a branch across the middle grove's culms.
const b2 = branch(5, 1, 170, 40);
group(b2[4], Math.PI / 2 - 0.3, 6, 1, 3);
group(twig(b2[2], -0.9, 60), Math.PI / 2 - 0.1, 4, 0.85, 2);

// Higher on the left, a shorter branch.
const b3 = branch(7, -1, 130, 30);
group(b3[4], Math.PI / 2 + 0.45, 6, 0.95, 3);

// Between them on the right, a short one.
const b6 = branch(8, 1, 100, 20);
group(b6[4], Math.PI / 2 - 0.5, 4, 0.85, 2);

// Near the top on the right: the crown, running off the top edge.
const b4 = branch(9, 1, 120, 25);
group(b4[4], Math.PI / 2 - 0.4, 6, 0.95, 3);
group(twig(b4[1], -1.2, 80), Math.PI / 2 - 0.2, 4, 0.8, 2);

// Young leaves high on the left, not yet darkened: zhong, short, held up and out.
const young = node(8);
const yx = young.p[0] - young.hw;
for (let k = 0; k < 3; k++) {
  leaf(
    yx - 4,
    young.p[1] - 6 - k * 6,
    -Math.PI / 2 - 0.55 - k * 0.32,
    rand(105, 135),
    21,
    'zhong',
    -0.15,
  );
}

// One low twig with a pair of leaves, so the culm's foot is not bare.
const b5 = branch(1, 1, 80, 10);
group(b5[4], Math.PI / 2 - 0.6, 2, 0.75, 1);

show({ x: 0, y: 0, w: canvas.width, h: canvas.height }, { mode: 'squint', maxSide: 700 });
dry();

/**
 * Passage 5: the seal.
 *
 * A square seal in cinnabar paste, pressed low on the left where the paper is empty.
 * It is cut in the red-line style: a border and two characters standing in red on the
 * paper, read from the right column to the left. The right column is 雨 (rain) and
 * the left 竹 (bamboo): bamboo in the rain, the subject. The strokes are square-
 * cornered as a stone cutter leaves them, and lightly loaded paste breaks on the paper
 * here and there, as a real impression does.
 */

// Cinnabar paste: vermilion warmed toward orange, a little carmine for depth.
palette('vermilion', '#d23c1c');
palette('carmine', '#9a1430');
palette('cinnabar', mix(['vermilion', 3], ['carmine', 1]));

const S = 74; // the seal's side, px
const X0 = 92;
const Y0 = 1612;
/** A point in the seal's own unit square, with a slight skew from an uneven press. */
const P = (u, v) => [X0 + u * S + v * 1.2, Y0 + v * S - u * 0.8];

/** One cut line through unit-square points, as a stroke of paste. */
function cut(points, width) {
  stroke({
    path: points.map(([u, v]) => P(u, v)),
    brush: { type: 'flat', width, streak: 0.3, stiffness: 0.9 },
    color: 'cinnabar',
    paint: 'semi_opaque',
    load: rand(0.72, 0.85),
    contact: rand(0.85, 0.95),
    corners: true,
    end: 'stop',
  });
}

// The border, a little heavier than the characters, as a worn stone's edge prints.
cut(
  [
    [0.03, 0.04],
    [0.97, 0.04],
  ],
  6,
);
cut(
  [
    [0.96, 0.03],
