  ],
  6,
);
cut(
  [
    [0.97, 0.96],
    [0.03, 0.96],
  ],
  6,
);
cut(
  [
    [0.04, 0.97],
    [0.04, 0.03],
  ],
  6,
);

// 雨, the right column: a cap stroke, the frame, the central stroke, four raindrops.
cut(
  [
    [0.54, 0.15],
    [0.88, 0.15],
  ],
  4,
);
cut(
  [
    [0.57, 0.86],
    [0.57, 0.29],
    [0.86, 0.29],
    [0.86, 0.86],
  ],
  4,
);
cut(
  [
    [0.715, 0.15],
    [0.715, 0.8],
  ],
  4,
);
for (const [u, v] of [
  [0.62, 0.43],
  [0.62, 0.62],
  [0.77, 0.43],
  [0.77, 0.62],
]) {
  cut(
